def to_base(number, base):
    if base < 2 or base > 36:
        raise ValueError(f"Base must be between 2 and 36, got {base}")

    if number == 0:
        return "0"

    is_negative = number < 0
    number = abs(number)

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = []

    while number > 0:
        result.append(digits[number % base])
        number //= base

    result_str = ''.join(reversed(result))
    return '-' + result_str if is_negative else result_str


def from_base(text, base):
    if base < 2 or base > 36:
        raise ValueError(f"Base must be between 2 and 36, got {base}")

    if not text:
        raise ValueError("Empty string")

    if text == "-":
        raise ValueError("Lone minus sign")

    is_negative = False
    if text.startswith("-"):
        is_negative = True
        text = text[1:]

    if not text:
        raise ValueError("Lone minus sign")

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    valid_chars = digits[:base]

    result = 0
    for char in text:
        lower_char = char.lower()
        if lower_char not in valid_chars:
            raise ValueError(f"Invalid character '{char}' for base {base}")
        result = result * base + digits.index(lower_char)

    return -result if is_negative else result
